package com.powerliq.marketdata;
import com.fasterxml.jackson.databind.*;import com.powerliq.events.*;import java.time.Duration;import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.*;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import software.amazon.awssdk.auth.credentials.DefaultCredentialsProvider;import software.amazon.awssdk.regions.Region;import software.amazon.awssdk.services.sqs.SqsClient;import software.amazon.awssdk.services.sqs.model.*;
@Component @ConditionalOnProperty(name="powerliq.events.consumer.enabled",havingValue="true")
public class MarketPriceQueueConsumer{
 private static final Logger LOG=LoggerFactory.getLogger(MarketPriceQueueConsumer.class);private final SqsClient sqs;private final ObjectMapper json;private final MarketDataService service;private final String queueUrl;private final JavaType eventType;
 public MarketPriceQueueConsumer(SqsClient sqs,ObjectMapper json,MarketDataService service,@Value("${powerliq.events.queue-url}")String queueUrl){this.sqs=sqs;this.json=json;this.service=service;this.queueUrl=queueUrl;eventType=json.getTypeFactory().constructParametricType(EventEnvelope.class,MarketPriceRevisionV1.class);}
 @Scheduled(fixedDelayString="${powerliq.events.consumer-delay:1000}")public void poll(){ReceiveMessageResponse response=sqs.receiveMessage(r->r.queueUrl(queueUrl).maxNumberOfMessages(10).waitTimeSeconds(10).visibilityTimeout(30));for(Message message:response.messages())process(message);}
 private void process(Message message){try{JsonNode detail=json.readTree(message.body()).required("detail");EventEnvelope<MarketPriceRevisionV1> event=json.readValue(detail.traverse(json),eventType);service.consume(event);sqs.deleteMessage(r->r.queueUrl(queueUrl).receiptHandle(message.receiptHandle()));}catch(Exception e){LOG.error("Market-price event processing failed messageId={}",message.messageId(),e);}}
 @Configuration @ConditionalOnProperty(name="powerliq.events.consumer.enabled",havingValue="true")static class ClientConfiguration{@Bean SqsClient sqsClient(@Value("${powerliq.aws.region:eu-west-2}")String region){return SqsClient.builder().region(Region.of(region)).credentialsProvider(DefaultCredentialsProvider.create()).overrideConfiguration(c->c.apiCallTimeout(Duration.ofSeconds(15)).apiCallAttemptTimeout(Duration.ofSeconds(12))).build();}}
}
